from pathlib import Path
import chromedriver_autoinstaller

url_base = "https://www.bcb.gov.br/en/publications/copomminutes/"
output_dir = Path(__file__).parent / 'atas_copom'
output_dir.mkdir(exist_ok=True)

chromedriver_autoinstaller.install()
driver = webdriver.Chrome()
def download_pdf(data):
    try:
        
        driver.get(f"{url_base}{data}")
        driver.implicitly_wait(10)
        download_button = WebDriverWait(driver, 10).until(
            EC.presence_of_element_located((By.XPATH, "//a[contains(@href, 'copomminutes') and contains(@href, '.pdf')]"))
        )
        pdf_url = download_button.get_attribute("href")
        print(f"Baixando ata do Copom: {pdf_url}")
        response = requests.get(pdf_url)
        file_name = os.path.join(output_dir, f"Copom_{data}.pdf")

        
        with open(file_name, "wb") as file:
            file.write(response.content)
        return file_name
    except Exception as e:
        print(f"Erro ao baixar o PDF para a data {data}: {e}")
        return None

for data in datas_copom:   
    file_path = download_pdf(data)
    if file_path:
        print(f"Arquivo salvo: {file_path}")
    else:
        print(f"Falha ao baixar o arquivo para a data {data}")
        
        

def clean_text(raw_text):
    lines = raw_text.split('\n')
    clean_lines = []

    for line in lines:
        line = line.strip()
        if not line or re.match(r'^\s*\d+[ªº]?\.*\s*$', line):
            continue
        if re.match(r'^[A-Z]{2,}$', line):  # siglas apenas
            continue
        if 'bcb.gov.br' in line.lower():
            continue
        if re.search(r'\b\d{1,2}[/.-]\d{1,2}[/.-]\d{2,4}\b', line):  # tipo 31/01/2024 ou 31.01.24
            continue
        if re.search(r'\b\d{4}[-/]\d{2}[-/]\d{2}\b', line):  # tipo 2024-01-31
            continue
        if re.search(r'\b\d{1,2}\s+de\s+\w+\s+de\s+\d{4}\b', line.lower()):  # tipo 30 de janeiro de 2024
            continue
        if re.search(r'\b\w+\s+de\s+\d{4}\b', line.lower()):  # tipo Janeiro de 2024
            continue
        if re.search(r'\b(reunião|ata|copom|presentes?:|local:|edifício|horários?)\b', line.lower()):
            continue
        line = re.sub(r'^\s*\d+[ªº]?\.?\s*', '', line)
        line = re.sub(r'\s+\d+[ªº]?\s*$', '', line)
        line = re.sub(r'\s+', ' ', line)
        line = re.sub(r'\s+([.,;:])', r'\1', line)
        if len(line.split()) < 6:
            continue
        clean_lines.append(line)
    full_text = ' '.join(clean_lines)
    full_text = re.sub(r'\s+([?.!])', r'\1', full_text)
    full_text = re.sub(r'\s{2,}', ' ', full_text)
    
